
create table public.households (id uuid primary key default gen_random_uuid(), pairing_hash bytea not null, created_at timestamptz not null default now());
create table public.household_members (household_id uuid not null references public.households(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, joined_at timestamptz not null default now(), primary key (household_id,user_id));
alter table public.households enable row level security; alter table public.household_members enable row level security;
alter table public.dsa_attempts add column household_id uuid references public.households(id) on delete cascade not null;
alter table public.learning_progress add column household_id uuid references public.households(id) on delete cascade not null;
alter table public.applications add column household_id uuid references public.households(id) on delete cascade not null;
alter table public.recruiters add column household_id uuid references public.households(id) on delete cascade not null;
alter table public.daily_goals add column household_id uuid references public.households(id) on delete cascade not null;
create or replace function public.is_household_member(target_household uuid) returns boolean language sql stable security invoker set search_path=public as $$select exists(select 1 from public.household_members where household_id=target_household and user_id=(select auth.uid()))$$;
create policy "view own membership" on public.household_members for select to authenticated using (user_id=(select auth.uid()));
create or replace function public.create_household() returns table(pairing_code text,household_id uuid) language plpgsql security definer set search_path=public,extensions as $$declare i uuid:=gen_random_uuid(); c text:=encode(gen_random_bytes(18),'hex');begin insert into public.households(id,pairing_hash)values(i,digest(c,'sha256'));insert into public.household_members(household_id,user_id)values(i,auth.uid());return query select c,i;end;$$;
create or replace function public.join_household(code text) returns uuid language plpgsql security definer set search_path=public,extensions as $$declare i uuid;begin select id into i from public.households where pairing_hash=digest(code,'sha256');if i is null then raise exception 'Invalid pairing code';end if;insert into public.household_members(household_id,user_id)values(i,auth.uid())on conflict do nothing;return i;end;$$;
revoke all on function public.create_household() from public,anon; revoke all on function public.join_household(text) from public,anon; grant execute on function public.create_household() to authenticated; grant execute on function public.join_household(text) to authenticated;
drop policy "own dsa attempts" on public.dsa_attempts; drop policy "own learning progress" on public.learning_progress; drop policy "own applications" on public.applications; drop policy "own recruiters" on public.recruiters; drop policy "own daily goals" on public.daily_goals;
create policy "household dsa" on public.dsa_attempts for all to authenticated using (public.is_household_member(household_id)) with check (public.is_household_member(household_id)); create policy "household learning" on public.learning_progress for all to authenticated using (public.is_household_member(household_id)) with check (public.is_household_member(household_id)); create policy "household applications" on public.applications for all to authenticated using (public.is_household_member(household_id)) with check (public.is_household_member(household_id)); create policy "household recruiters" on public.recruiters for all to authenticated using (public.is_household_member(household_id)) with check (public.is_household_member(household_id)); create policy "household goals" on public.daily_goals for all to authenticated using (public.is_household_member(household_id)) with check (public.is_household_member(household_id));
alter table public.learning_progress drop constraint learning_progress_user_id_curriculum_external_id_key; alter table public.learning_progress add constraint learning_progress_household_curriculum_external_id_key unique (household_id,curriculum,external_id);
